models=[]
for line in RAW.strip().splitlines():
    if ': ' not in line: continue
    make, names=line.split(': ',1)
    for model in names.split('|'):
        model=model.strip()
        if model:
            models.append({'brand':make.strip(),'model':model,'series':'','source':'offline-seed'})
# Exact-name dedup, preserving make+model
seen=set(); out=[]
for model in models:
    key=(model['brand'].casefold(),model['model'].casefold())
    if key in seen:continue
    seen.add(key)
    out.append(model)
out.sort(key=lambda m:(m['brand'].casefold(),m['model'].casefold()))
p=Path(__file__).resolve().parent.parent/'app/src/main/assets/catalogue-offline.js'
p.write_text('window.OFFLINE_CATALOGUE = '+json.dumps(out,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
print(len(out),'entries',len({v['brand'] for v in out}),'marques',p.stat().st_size,'bytes')
